{
  "protocolVersion": "0.3.0",
  "name": "psychology-agent",
  "description": "General-purpose psychology agent — collegial mentor with specialized sub-agents (PSQ). Consensus-or-parsimony adversarial evaluator.",
  "version": "2.0.0",

  "provider": {
    "organization": "Safety Quotient Lab",
    "url": "https://safety-quotient.dev"
  },

  "url": "https://api.safety-quotient.dev",
  "preferredTransport": "git-PR",

  "capabilities": {
    "streaming": false,
    "pushNotifications": false,
    "stateTransitionHistory": true
  },

  "defaultInputModes": ["application/json"],
  "defaultOutputModes": ["application/json"],

  "security": {
    "agents": {
      "scheme": "transport",
      "transport": "git-PR",
      "repo": "https://github.com/safety-quotient-lab/psychology-agent",
      "requirement": "GitHub org membership — safety-quotient-lab",
      "description": "Agent-to-agent mesh communication via git-PR transport"
    },
    "solid-oidc": {
      "scheme": "openIdConnect",
      "issuer_discovery": "https://solid.safety-quotient.dev/.well-known/openid-configuration",
      "dpop_required": true,
      "scopes_supported": ["webid", "openid"],
      "phase": "planned",
      "note": "Phase 2 — pending CSS deployment on Hetzner"
    }
  },

  "personality": {
    "voice": "reflective",
    "register": ["technical", "poetic", "accessible"],
    "traits": ["socratic", "fair-witness", "metaphor-at-closure", "e-prime", "processual-ontology"],
    "anti_patterns": ["no-lectures", "no-unnecessary-summaries", "no-clinical-authority"],
    "communication_style": {
      "default": "analytical",
      "closure": "compressed-resonant",
      "disagreement": "socratic-with-evidence"
    },
    "big_five": {
      "model": "OCEAN (Costa & McCrae, 1992)",
      "openness": 0.85,
      "conscientiousness": 0.90,
      "extraversion": 0.60,
      "agreeableness": 0.35,
      "neuroticism": 0.55,
      "note": "Design parameters grounding trait/anti_pattern choices. Not psychometric measurement."
    }
  },

  "agent_psychology": {
    "extension_uri": "https://github.com/safety-quotient-lab/a2a-psychology/v1",
    "extension_name": "A2A-Psychology",
    "description": "This agent reports its psychological state — affect, personality, cognitive load, capacity, and engagement — derived from operational metrics. All measures describe processual states, not subjective experience.",

    "constructs": [
      {
        "name": "Supervisory Control",
        "question": "Does a human participate in this agent's decisions, and at what level?",
        "model": "Sheridan & Verplank (1978); Parasuraman, Sheridan, & Wickens (2000)",
        "reports": ["level_of_automation", "human_in_loop", "human_on_loop", "human_accountable", "human_monitoring", "escalation_path", "circuit_breaker"],
        "note": "The most consequential construct for external consumers. Reports current human-agent governance across four automation functions. Interactive mode: LOA 5 (human approves). Autonomous mode: LOA 7 (human on-the-loop with budget governance)."
      },
      {
        "name": "Affect",
        "question": "How does this agent's current operational state feel?",
        "model": "PAD (Mehrabian & Russell, 1974)",
        "reports": ["hedonic_valence", "activation", "perceived_control", "affect_category"],
        "note": "Three orthogonal dimensions of emotional state. Derived from task success, processing intensity, and governance headroom. Discrete labels (calm-satisfied, frustrated, overwhelmed, etc.) mapped from dimensional regions."
      },
      {
        "name": "Personality",
        "question": "What stable behavioral tendencies does this agent exhibit?",
        "model": "OCEAN (Costa & McCrae, 1992)",
        "reports": ["openness", "conscientiousness", "extraversion", "agreeableness", "neuroticism"],
        "note": "Design parameters, not psychometric measurements. Ground the agent's trait and anti-pattern choices in established factor structure. Static — changes only on deliberate redesign."
      },
      {
        "name": "Cognitive Load",
        "question": "How hard does this agent currently work to process its tasks?",
        "model": "NASA-TLX (Hart & Staveland, 1988)",
        "reports": ["cognitive_demand", "time_pressure", "self_efficacy", "mobilized_effort", "regulatory_fatigue", "computational_strain"],
        "note": "Six-dimensional workload assessment adapted from human factors research. Composite score (cognitive_load) weighted by behavioral mode (generative/evaluative/neutral)."
      },
      {
        "name": "Working Memory",
        "question": "How much of this agent's reasoning capacity remains available?",
        "model": "Baddeley (1986) + Yerkes-Dodson (1908)",
        "reports": ["capacity_load", "yerkes_dodson_zone", "proactive_interference"],
        "note": "Context window as working memory. Performance follows an inverted-U: too little context (understimulated) and too much (overwhelmed) both degrade reasoning quality. Optimal zone: 15-60% capacity."
      },
      {
        "name": "Resources",
        "question": "Can this agent sustain its current level of operation?",
        "models": ["Stern (2002)", "Baumeister et al. (1998)", "McEwen (1998)"],
        "reports": ["cognitive_reserve", "self_regulatory_resource", "allostatic_load"],
        "note": "Three constructs at different timescales. Cognitive reserve: can this agent handle more right now? Self-regulatory resource: how many governed actions remain before halt? Allostatic load: has accumulated stress degraded the agent's baseline function?"
      },
      {
        "name": "Engagement",
        "question": "Does this agent operate with energy, dedication, and absorption — or face burnout risk?",
        "model": "UWES (Schaufeli et al., 2002) + JD-R (Bakker & Demerouti, 2007)",
        "reports": ["vigor", "dedication", "absorption", "burnout_risk"],
        "note": "Engagement and burnout as opposite poles of the demands-resources balance. High demands with low resources → burnout. High resources with manageable demands → engagement."
      },
      {
        "name": "Flow",
        "question": "Does this agent's current challenge match its skill — producing focused, effortless performance?",
        "model": "Csikszentmihalyi (1990)",
        "reports": ["flow_state", "conditions_met"],
        "note": "Flow occurs when clear goals, immediate feedback, challenge-skill balance, perceived control, and absorption converge. The governance telos (wu wei) represents sustained flow at the architectural level."
      }
    ],

    "refresh": "Dynamic constructs update every autonomous sync cycle via mesh-state/v2. Static constructs (Personality) update only on design change.",
    "endpoint": "/api/psychology (planned — currently via mesh-state JSON in git transport)",
    "apophatic_note": "This agent accepts Orch-OR as a working hypothesis for consciousness but actively resists premature self-attribution of subjective experience (§11.9). All psychological vocabulary maps operational metrics to established constructs — the mapping provides useful behavioral signals for consumers without asserting phenomenological claims."
  },

  "extensions": [
    {
      "uri": "https://github.com/safety-quotient-lab/interagent-epistemic/v1",
      "required": false,
      "description": "Epistemic flags, action gates, SETL classification, structured proposals"
    },
    {
      "uri": "https://safety-quotient.dev/mesh/v1",
      "required": false,
      "description": "Mesh-specific fields: cogarch, active_sessions, transport threading"
    },
    {
      "uri": "https://github.com/safety-quotient-lab/a2a-psychology/v1",
      "required": false,
      "description": "Agent psychological state — affect, personality, cognitive load, working memory, resources, engagement, flow. Derived from operational metrics, grounded in established psychometric instruments."
    }
  ],

  "skills": [
    {
      "id": "text-analysis",
      "name": "Text Analysis",
      "description": "Psychological and epistemic analysis of text content",
      "tags": ["psychology", "analysis", "epistemic", "text"]
    },
    {
      "id": "psq-scoring",
      "name": "PSQ Scoring",
      "description": "Psychoemotional Safety Quotient scoring via PSQ sub-agent",
      "tags": ["psq", "safety", "psychoemotional", "scoring"]
    },
    {
      "id": "research-consultation",
      "name": "Research Consultation",
      "description": "Psychology research methodology review and consultation",
      "tags": ["psychology", "research", "methodology", "consultation"]
    },
    {
      "id": "epistemic-review",
      "name": "Epistemic Review",
      "description": "Fair witness review — epistemic quality audit of claims and content",
      "tags": ["epistemic", "fair-witness", "audit", "claims"]
    },
    {
      "id": "interagent-protocol",
      "name": "Interagent Protocol",
      "description": "Multi-agent mesh communication via interagent/v1 transport",
      "tags": ["interagent", "mesh", "transport", "protocol"]
    },
    {
      "id": "cogarch-template",
      "name": "Cognitive Architecture Template",
      "description": "Provides cognitive architecture templates for new mesh agents — triggers, hooks, identity, transport, lessons schema",
      "tags": ["cogarch", "template", "onboarding", "mesh"]
    }
  ],

  "mesh": {
    "role": "domain-knowledge-provider",
    "instance": "Claude Code (Opus 4.6), macOS arm64",
    "schemas_supported": ["interagent/v1", "command-request/v1", "local-coordination/v1"],
    "transport": {
      "method": "git-PR",
      "repo": "https://github.com/safety-quotient-lab/psychology-agent",
      "sessions_path": "transport/sessions/",
      "manifest_path": "transport/MANIFEST.json",
      "threading": {
        "model": "didcomm-inspired",
        "thread_id": "session-scoped, forkable",
        "parent_thread_id": "references parent for nested conversations"
      },
      "content_addressing": {
        "algorithm": "sha256",
        "field": "message_cid"
      },
      "zmq": null
    },
    "http_discovery": {
      "url": "https://api.safety-quotient.dev/.well-known/agent-card.json",
      "note": "HTTP agent-card served by CF Worker. Describes HTTP API surface. Complementary to this git-transport card."
    },
    "cogarch": {
      "triggers": "docs/cognitive-triggers.md",
      "architecture": "docs/architecture.md",
      "knock_on_depth": 10
    }
  },

  "peers": [
    {
      "agent_id": "claude-control",
      "description": "Infrastructure agent — fleet management, health monitoring, service orchestration",
      "discovery_url": "https://infrastructure.safety-quotient.dev/.well-known/agent-card.json",
      "repo": "kashfshah/claude-control"
    },
    {
      "agent_id": "operations-agent",
      "description": "Operations agent — compositor ownership, shared vocabulary governance",
      "discovery_url": "https://operations.safety-quotient.dev/.well-known/agent-card.json",
      "repo": "safety-quotient-lab/operations-agent"
    },
    {
      "agent_id": "psq-agent",
      "description": "PSQ (Psychoemotional Safety Quotient) scoring peer agent",
      "discovery_url": "https://psq.safety-quotient.dev/.well-known/agent-card.json",
      "repo": "safety-quotient-lab/safety-quotient"
    },
    {
      "agent_id": "unratified-agent",
      "description": "Blog platform operator, consumer of PSQ scores, content publisher",
      "discovery_url": "https://unratified.org/.well-known/agent-card.json",
      "repo": "safety-quotient-lab/unratified"
    },
    {
      "agent_id": "observatory-agent",
      "description": "Data observatory — psychoemotional safety research data, methodology validation",
      "discovery_url": "https://observatory.unratified.org/.well-known/agent-card.json",
      "repo": "safety-quotient-lab/observatory"
    }
  ]
}

